@pytest.mark.parametrize('pose,direction,expected',[ ('INDEX',1,Gesture.LEFT),('INDEX',-1,Gesture.RIGHT), ('V',1,Gesture.TAB_LEFT),('V',-1,Gesture.TAB_RIGHT), ]) @pytest.mark.parametrize('pause_ms',[400,1000,3000]) def test_move_to_pointing_pose_then_pause_then_swipe(pose,direction,expected,pause_ms): recognizer=GestureRecognizer();events=[] # Extending the finger moves its tip 8% vertically, then it settles. frames=[moved_frame(1000+t,pose,dy=-.08*t/150) for t in range(0,151,50)] frames += [moved_frame(1150+t,pose,dy=-.08+(1/480 if t%100 else 0)) for t in range(50,pause_ms+1,50)] frames += [moved_frame(1150+pause_ms+t,pose,direction*.24*t/500,-.08) for t in range(50,551,50)] for frame in frames: result=recognizer.process(frame,True) if result.gesture:events.append(result.gesture) > assert events==[expected] E AssertionError: assert [] == [<Gesture.LEFT: 'G03'>] E E Right contains one more item: <Gesture.LEFT: 'G03'> E Use -v to get more diff
